import { describe, expect, it } from 'vitest';
import { cleanApiReport } from './api_report.ts';

describe('cleanApiReport', () => {
  it('drops the release tag and undocumented markers and keeps the signatures', () => {
    const report = [
      '## API Report File for "@arkham/util"',
      '',
      '> Do not edit this file. It is a report generated by [API Extractor](https://api-extractor.com/).',
      '',
      '```ts',
      '',
      '// @public',
      'export interface Doom {',
      '    // (undocumented)',
      '    amount: number;',
      '}',
      '',
      '// @public (undocumented)',
      'export const PACKAGE_NAME = "@arkham/util";',
      '',
      '// (No @packageDocumentation comment for this package)',
      '',
      '```',
    ].join('\r\n');

    const cleaned = cleanApiReport(report);

    expect(cleaned).toBe(
      [
        '## API Report File for "@arkham/util"',
        '',
        '> Generated by `pnpm api:report` with [API Extractor](https://api-extractor.com/); do not edit. ' +
          'A change here is a change to what other packages can use.',
        '',
        '```ts',
        '',
        'export interface Doom {',
        '    amount: number;',
        '}',
        '',
        'export const PACKAGE_NAME = "@arkham/util";',
        '',
        '```',
      ].join('\n'),
    );
  });
});
